scenario = "a fake random source that counts how often it is asked"
class Rng:
    """A fake random source: answers the given numbers one after another (repeating the last) and counts how often it was asked."""
    def __init__(self, *values):
        self.values = values
        self.calls = 0

    def __call__(self):
        value = self.values[min(self.calls, len(self.values) - 1)]
        self.calls += 1
        return value
